-- Generated by tools/build_action_data.py; do not edit.
return {["scripts/actions/spells/black/waterja.lua"]={["Path"]="scripts/actions/spells/black/waterja.lua",["SHA256"]="fc25e774ac23b5a73d8be73b50456088a89995aa46644a28b3fa42a1b55e529c",["Text"]="-----------------------------------\n-- Spell: Waterja\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/1000_needles.lua"]={["Path"]="scripts/actions/spells/blue/1000_needles.lua",["SHA256"]="954ee9324c5ec14ed48d8c827a1cafee146fb12c94bd8721da35148435ab8840",["Text"]="-----------------------------------\n-- Spell: 1000 Needles\n-- Shoots multiple needles at enemies within range\n-- Spell cost: 350 MP\n-- Monster Type: Plantoid\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 5\n-- Stat Bonus: VIT+3, AGI+3\n-- Level: 62\n-- Casting Time: 12 seconds\n-- Recast Time: 120 seconds\n-- Bursts on Light affects accuracy only\n-- Combos: Beast Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.PLANTOID\n    params.tpModifier     = xi.spells.blue.tpMod.DAMAGE\n    params.attackType     = xi.attackType.MAGICAL\n    params.damageType     = xi.damageType.LIGHT\n    params.skillchainType = xi.skillchainType.COMPRESSION\n\n    params.bonusMacc     = -50 -- 50 magic accuracy penalty\n    params.numHits       = 1\n    params.ftp0          = 1.5\n    params.ftp1500       = 1.5\n    params.ftp3000       = 1.5\n    params.ftpAzure      = 1.5\n    params.baseDamageCap = 49\n\n    params.str_wsc = 1.0\n    params.dex_wsc = 1.5\n    params.int_wsc = 2.0\n    params.mnd_wsc = 1.0\n    params.chr_wsc = 1.0\n\n    local damage = 1000\n    local maccParams =\n    {\n        magicalElement = xi.element.LIGHT,\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.BLUE_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n        bonusMacc      = -50\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, maccParams)\n    if resist == 1 then\n        local targets = spell:getTotalTargets()\n        damage = damage / targets\n        damage = xi.spells.blue.applySpellDamage(caster, target, spell, damage, params)\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_RESIST)\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/actinic_burst.lua"]={["Path"]="scripts/actions/spells/blue/actinic_burst.lua",["SHA256"]="f04055f3c705dd92994f58122bf6ae85c427b232dbac98d59d0a15092822082b",["Text"]="-----------------------------------\n-- Spell: Actinic Burst\n-- Greatly lowers the accuracy of enemies within range for a brief period of time\n-- Spell cost: 24 MP\n-- Monster Type: Luminions\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 4\n-- Stat Bonus: CHR+2, HP+20\n-- Level: 74\n-- Casting Time: 0.5 seconds\n-- Recast Time: 60 seconds\n-- Effect Time: About 15 seconds\n-- Magic Bursts on: Transfixion, Fusion, and Light\n-- Combos: Auto Refresh\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.LUMINION\n    params.effect          = xi.effect.FLASH\n    params.power           = 0 -- Power is handled in hit rate calculations\n    params.tick            = 0\n    params.duration        = 16 -- This may be randomized, but the data was from Brenner\n    params.resistThreshold = 0.25\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/amorphic_spikes.lua"]={["Path"]="scripts/actions/spells/blue/amorphic_spikes.lua",["SHA256"]="68b61bfd48fc358e5a488f62a3373566acf5680f561b2244e5fbf00e6d2e1b66",["Text"]="-----------------------------------\n-- Spell: Amorphic Spikes\n-- Delivers a fivefold attack. Danage varies with TP\n-- Spell cost: 79 MP\n-- Monster Type: AMORPH\n-- Spell Type: Physical (Piercing)\n-- Blue Magic Points: 4\n-- Stat Bonus: INT+5 MND+2\n-- Level: 98\n-- Casting Time: 0.5 seconds\n-- Recast Time: 58.25 seconds\n-- Skillchain Element(s): Gravitation/Transfixion\n-- Combos: Gilfinder / Treasure Hunter\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.AMORPH\n    params.tpModifier = xi.spells.blue.tpMod.ATTACK\n\n    if params.hasAzureLore then\n        params.bonusAcc = 70\n    elseif params.hasChainAffinity then\n        params.bonusAcc = math.floor(caster:getTP() / 50)\n    end\n\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.PIERCING\n    params.skillchainType  = xi.skillchainType.GRAVITATION\n    params.skillchainType2 = xi.skillchainType.TRANSFIXION\n\n    params.numHits       = 5\n    params.ftp0          = 1.0\n    params.ftp1500       = 1.375\n    params.ftp3000       = 1.750 -- as per https://wiki.ffo.jp/html/24665.html\n    params.ftpAzure      = 2.125 -- guessing as no wiki has this info.\n    params.baseDamageCap = 75\n\n    params.dex_wsc = 0.20\n    params.int_wsc = 0.20\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/amplification.lua"]={["Path"]="scripts/actions/spells/blue/amplification.lua",["SHA256"]="764512615b40d1b4110218ded1c5dbb13a6972e75f76f95b3cb65d8946c0f516",["Text"]="-----------------------------------\n-- Spell: Amplification\n-- Enhances magic attack and magic defense\n-- Spell cost: 48 MP\n-- Monster Type: Amorphs\n-- Spell Type: Magical (Water)\n-- Blue Magic Points: 3\n-- Stat Bonus: HP-5, MP+5\n-- Level: 70\n-- Casting Time: 7 seconds\n-- Recast Time: 120 seconds\n-- Duration: 90 seconds\n-----------------------------------\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local duration     = xi.spells.blue.calculateDurationWithDiffusion(caster, 90)\n    local returnEffect = xi.effect.MAGIC_ATK_BOOST\n\n    local actionOne = target:addStatusEffect(xi.effect.MAGIC_ATK_BOOST, { power = 10, duration = duration, origin = caster })\n    local actionTwo = target:addStatusEffect(xi.effect.MAGIC_DEF_BOOST, { power = 10, duration = duration, origin = caster })\n\n    if not actionOne and not actionTwo then -- both statuses fail to apply\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    elseif not actionOne and actionTwo then -- the first status fails to apply\n        returnEffect = xi.effect.MAGIC_DEF_BOOST\n    elseif actionOne and not actionTwo then -- the second status fails to apply\n        returnEffect = xi.effect.MAGIC_ATK_BOOST\n    end\n\n    return returnEffect\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/animating_wail.lua"]={["Path"]="scripts/actions/spells/blue/animating_wail.lua",["SHA256"]="0aed646411700a77cd13022a59d29198242ffba40e42987f2df07b183a74bb35",["Text"]="-----------------------------------\n-- Spell: Animating Wail\n-- Increases attack speed\n-- Spell cost: 53 MP\n-- Monster Type: Undead\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 5\n-- Stat Bonus: HP+20\n-- Level: 79\n-- Casting Time: 2 Seconds\n-- Recast Time: 45 Seconds\n-- 5 minutes\n-----------------------------------\n-- Combos: Dual Wield\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power    = 1500 -- 15%\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 300)\n\n    if not target:addStatusEffect(xi.effect.HASTE, { power = power, duration = duration, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.HASTE\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/asuran_claws.lua"]={["Path"]="scripts/actions/spells/blue/asuran_claws.lua",["SHA256"]="01a2ea0fe7952463cfb7c5c62fc5a77258801f7e07ab89c108c3183fc3d06996",["Text"]="-----------------------------------\n-- Spell: Asuran Claws\n-- Delivers a sixfold attack. Accuracy varies with TP\n-- Spell cost: 81 MP\n-- Monster Type: Beasts\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 2\n-- Stat Bonus: AGI +3\n-- Level: 70\n-- Casting Time: 3 seconds\n-- Recast Time: 60 seconds\n-- Skillchain Element(s): Liquefaction/Impaction\n-- Combos: Counter\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.BEAST\n    params.tpModifier = xi.spells.blue.tpMod.ACC\n\n    -- TODO: made up\n    if params.hasAzureLore then\n        params.bonusAcc = 70\n    elseif params.hasChainAffinity then\n        params.bonusAcc = math.floor(caster:getTP() / 50)\n    end\n\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.HAND_TO_HAND\n    params.skillchainType  = xi.skillchainType.LIQUEFACTION\n    params.skillchainType2 = xi.skillchainType.IMPACTION\n\n    params.numHits       = 6\n    params.ftp0          = 0.625\n    params.ftp1500       = 0.625\n    params.ftp3000       = 0.625\n    params.ftpAzure      = 0.625\n    params.baseDamageCap = 999 -- uncapped in retail. was 21 here before?\n    params.attackMult    = 1.05\n\n    -- D seems low for its level, but the spell never did good damage, so a low D is a good way of keeping overall damage down.\n    -- More discussion on https://ffxiclopedia.fandom.com/wiki/Talk:Asuran_Claws\n    params.str_wsc = 0.1\n    params.dex_wsc = 0.1\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/auroral_drape.lua"]={["Path"]="scripts/actions/spells/blue/auroral_drape.lua",["SHA256"]="2fc5c962675b653e2ef352108db5472abaf2385b1ea548f859e9d053e597e0a8",["Text"]="-----------------------------------\n-- Spell: Auroral Drape\n-- Silences and blinds enemies within range.\n-- Spell cost: 51 MP\n-- Monster Type: Empty\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 4\n-- Stat Bonus: INT+3 CHR-2\n-- Level: 84\n-- Casting Time: Casting Time: 4 seconds\n-- Recast Time: Recast Time: 60 seconds\n-- Duration: 40-60 seconds\n-- Magic Bursts on: None\n-- Combos: Fast Cast\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.EMPTY\n    params.effect          = xi.effect.SILENCE\n    params.power           = 1\n    params.tick            = 0\n    params.duration        = 60\n    params.resistThreshold = 0.50\n    params.isGaze          = false\n    params.isConal         = false\n\n    local maccParams =\n    {\n        magicalElement = spell:getElement(),\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.BLUE_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, maccParams)\n\n    -- Handle status effects.\n    -- Not sure if there's a better way to implement both status effects\n    local effectTable =\n    {\n        [1] = { xi.effect.BIND, 25, 0, 40 + math.floor(resist * 20) },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/awful_eye.lua"]={["Path"]="scripts/actions/spells/blue/awful_eye.lua",["SHA256"]="079a1651e56bb1001757ff92933916f51f7755ae3a7f908ae60e8caf3364efb1",["Text"]="-----------------------------------\n-- Spell: Awful Eye\n-- Lowers Strength of enemies within a fan-shaped area originating from the caster\n-- Spell cost: 32 MP\n-- Monster Type: Lizards\n-- Spell Type: Magical (Water)\n-- Blue Magic Points: 2\n-- Stat Bonus: MND+1\n-- Level: 46\n-- Casting Time: 2.5 seconds\n-- Recast Time: 60 seconds\n-- Magic Bursts on: Reverberation, Distortion, and Darkness\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n\n    params.ecosystem       = xi.ecosystem.LIZARD\n    params.effect          = xi.effect.STR_DOWN\n    params.power           = 30\n    params.tick            = 1\n    params.duration        = 30\n    params.resistThreshold = 0.5\n    params.isGaze          = true\n    params.isConal         = true\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/bad_breath.lua"]={["Path"]="scripts/actions/spells/blue/bad_breath.lua",["SHA256"]="bbfccd9aad189fcb3329d66cd7ca5264339626519301b30b1e6d5c6c2def8275",["Text"]="-----------------------------------\n-- Spell: Bad Breath\n-- Deals earth damage that inflicts multiple status ailments on enemies within a fan-shaped area originating from the caster\n-- Spell cost: 212 MP\n-- Monster Type: Plantoids\n-- Spell Type: Magical (Earth)\n-- Blue Magic Points: 5\n-- Stat Bonus: INT+2, MND+2\n-- Level: 61\n-- Casting Time: 8.75 seconds\n-- Recast Time: 120 seconds\n-- Magic Bursts on: Scission, Gravitation, Darkness\n-- Combos: Fast Cast\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params = {}\n\n    params.ecosystem  = xi.ecosystem.PLANTOID\n    params.attackType = xi.attackType.BREATH\n    params.damageType = xi.damageType.EARTH\n    params.hpMod      = 8\n    params.lvlMod     = 3\n    params.isConal    = true\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useBreathSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.SLOW,      2000, 0, 60 },\n        [2] = { xi.effect.SILENCE,      1, 0, 60 },\n        [3] = { xi.effect.PARALYSIS,   15, 0, 60 },\n        [4] = { xi.effect.BIND,         1, 0, 60 },\n        [5] = { xi.effect.WEIGHT,      20, 0, 60 },\n        [6] = { xi.effect.POISON,       4, 0, 60 },\n        [7] = { xi.effect.BLINDNESS,   20, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/battery_charge.lua"]={["Path"]="scripts/actions/spells/blue/battery_charge.lua",["SHA256"]="70b67acc72d2786766cd086553940df4e0b7c5aba1b7fb90e539b0628bfe6637",["Text"]="-----------------------------------\n-- Spell: Battery Charge\n-- Gradually restores MP\n-- Spell cost: 50 MP\n-- Monster Type: Arcana\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 3\n-- Stat Bonus: MP+10, MND+1\n-- Level: 79\n-- Casting Time: 5 seconds\n-- Recast Time: 75 seconds\n-- Spell Duration: 100 ticks, 300 Seconds (5 Minutes)\n-----------------------------------\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power    = 3 + caster:getMod(xi.mod.ENHANCES_REFRESH)\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 300)\n\n    if not target:addStatusEffect(xi.effect.REFRESH, { power = power, duration = duration, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.REFRESH\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/battle_dance.lua"]={["Path"]="scripts/actions/spells/blue/battle_dance.lua",["SHA256"]="42f31ba9ce4f0d80c1811ee36af9e1d2e71c654cb074eae312f961b2e1ce97a7",["Text"]="-----------------------------------\n-- Spell: Battle Dance\n-- Delivers an area attack. Additional effect: DEX Down. Duration of effect varies with TP\n-- Spell cost: 12 MP\n-- Monster Type: Beastmen\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 3\n-- Stat Bonus: DEX+2\n-- Level: 12\n-- Casting Time: 1 second\n-- Recast Time: 10 seconds\n-- Skillchain Element(s): Impaction\n-- Combos: Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.BEASTMEN\n    params.tpModifier     = xi.spells.blue.tpMod.DURATION\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.SLASHING\n    params.skillchainType = xi.skillchainType.IMPACTION\n    params.shadowBehavior = xi.mobskills.shadowBehavior.NUMSHADOWS_3 -- This can take 1, 2 or 3. It seems to behave strangely. Tested in PVP.\n\n    params.numHits       = 1\n    params.ftp0          = 2.0\n    params.ftp1500       = 2.0\n    params.ftp3000       = 2.0\n    params.ftpAzure      = 2.0\n    params.baseDamageCap = 17\n    params.str_wsc       = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    local duration = 90\n\n    -- TODO: 0tp duration needs verification\n    if params.hasAzureLore then\n        duration = 800\n    elseif params.hasChainAffinity then\n        duration = xi.spells.blue.calculatefTP(caster:getTP(), 90, 480, 680)\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.DEX_DOWN, 9, 6, duration },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/blank_gaze.lua"]={["Path"]="scripts/actions/spells/blue/blank_gaze.lua",["SHA256"]="2fd05208bc0f1f86f8da75c885f22d65f08034a3b006a7692a93747cd5fee387",["Text"]="-----------------------------------\n-- Spell: Blank Gaze\n-- Removes one beneficial magic effect from an enemy\n-- Spell cost: 25 MP\n-- Monster Type: Beasts\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 2\n-- Stat Bonus: None\n-- Level: 38\n-- Casting Time: 3 seconds\n-- Recast Time: 10 seconds\n-- Magic Bursts on: Transfixion, Fusion, Light\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local effect = xi.effect.NONE\n    local params =\n    {\n        magicalElement = spell:getElement(),\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.BLUE_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, params)\n\n    if resist >= 0.25 then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n\n        -- Gaze move\n        if target:isFacing(caster) and caster:isFacing(target) then\n            effect = target:dispelStatusEffect()\n            spell:setMsg(xi.msg.basic.MAGIC_ERASE)\n            if effect == xi.effect.NONE then\n                spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n            end\n        end\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_RESIST)\n    end\n\n    return effect\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/blastbomb.lua"]={["Path"]="scripts/actions/spells/blue/blastbomb.lua",["SHA256"]="e876388b9f0cc9294b432a6a6fd76ca86ae89ddaf4e73d15892a8b0890e458b9",["Text"]="-----------------------------------\n-- Spell: Blastbomb\n-- Deals fire damage to enemies within area of effect. Additional effect: \"Bind\"\n-- Spell cost: 36 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Fire)\n-- Blue Magic Points: 2\n-- Stat Bonus: STR+1\n-- Level: 18\n-- Casting Time: 2.25 seconds\n-- Recast Time: 15 seconds\n-- Magic Bursts on: Liquefaction, Fusion, Light\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.BEASTMEN\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.FIRE\n    params.dStat       = xi.mod.INT\n\n    params.ftp0            = 1.375\n    params.dStatMultiplier = 1.0\n    params.baseDamageCap   = 30\n    params.halfThreshold   = 25\n    params.lowThreshold    = -10\n\n    params.int_wsc =  0.2\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.BIND, 1, 0, 30 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/blitzstrahl.lua"]={["Path"]="scripts/actions/spells/blue/blitzstrahl.lua",["SHA256"]="adb5429b744939d62c16ce1dd44721c7e5d5bc1a186135c3efaadbcf3e1ed64f",["Text"]="-----------------------------------\n-- Spell: Blitzstrahl\n-- Deals lightning damage to an enemy. Additional effect: \"Stun\"\n-- Spell cost: 70 MP\n-- Monster Type: Arcana\n-- Spell Type: Magical (Lightning)\n-- Blue Magic Points: 4\n-- Stat Bonus: DEX+3\n-- Level: 44\n-- Casting Time: 4.5 seconds\n-- Recast Time: 29.25 seconds\n-- Magic Bursts on: Impaction, Fragmentation, Light\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.ARCANA\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.THUNDER\n    params.dStat       = xi.mod.INT\n\n    params.ftp0            = 1.5625\n    params.dStatMultiplier = 1.0\n    params.baseDamageCap   = 61\n\n    params.int_wsc     = 0.3\n    params.mnd_wsc     = 0.1\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.STUN, 1, 0, 5 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/blood_drain.lua"]={["Path"]="scripts/actions/spells/blue/blood_drain.lua",["SHA256"]="088887f0f893c9f6caf9292ba1e5eb7a6ddb33e1bd695424d92cf03322b621d9",["Text"]="-----------------------------------\n-- Spell: Blood Drain\n-- Steals an enemy's HP. Ineffective against undead\n-- Spell cost: 10 MP\n-- Monster Type: Birds\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 2\n-- Stat Bonus: HP-5, MP+5\n-- Level: 20\n-- Casting Time: 4 seconds\n-- Recast Time: 90 seconds\n-- Magic Bursts on: Compression, Gravitation, Darkness\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.BIRD\n    params.attackType = xi.attackType.MAGICAL\n    params.damageType = xi.damageType.DARK\n\n    params.dmgMultiplier = 3\n\n    return xi.spells.blue.useDrainSpell(caster, target, spell, params, 0, false)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/blood_saber.lua"]={["Path"]="scripts/actions/spells/blue/blood_saber.lua",["SHA256"]="0c2782fb6a0e859c26067343d9446e06022709bd5faf6f2965c4929fcac097fd",["Text"]="-----------------------------------\n-- Spell: Blood Saber\n-- Steals HP from enemies within range. Ineffective against undead\n-- Spell cost: 25 MP\n-- Monster Type: Undead\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 2\n-- Stat Bonus: HP-5, MP+5\n-- Level: 48\n-- Casting Time: 4 seconds\n-- Recast Time: 90 seconds\n-- Magic Bursts on: Compression, Gravitation, Darkness\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.UNDEAD\n    params.attackType = xi.attackType.MAGICAL\n    params.damageType = xi.damageType.DARK\n\n    params.dmgMultiplier = 3.5\n\n    return xi.spells.blue.useDrainSpell(caster, target, spell, params, 0, false)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/bludgeon.lua"]={["Path"]="scripts/actions/spells/blue/bludgeon.lua",["SHA256"]="8e6dd5c968d6a59ede218f7fa62e9058bdc234364935ae50f9cb0ee7d08edfe8",["Text"]="-----------------------------------\n-- Spell: Bludgeon\n-- Delivers a threefold attack. Accuracy varies with TP\n-- Spell cost: 16 MP\n-- Monster Type: Arcana\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 2\n-- Stat Bonus: STR+1\n-- Level: 18\n-- Casting Time: 0.5 seconds\n-- Recast Time: 11.75 seconds\n-- Skillchain Element(s): Liquefaction\n-- Combos: Undead Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.ARCANA\n    params.tpModifier = xi.spells.blue.tpMod.ACC\n\n    -- This is entirely made up, apparently.\n    if params.hasAzureLore then\n        params.bonusAcc = 70\n    elseif params.hasChainAffinity then\n        params.bonusAcc = math.floor(caster:getTP() / 50)\n    end\n\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.HAND_TO_HAND\n    params.skillchainType = xi.skillchainType.LIQUEFACTION\n\n    params.numHits       = 3\n    params.ftp0          = 1.0\n    params.ftp1500       = 1.0\n    params.ftp3000       = 1.0\n    params.ftpAzure      = 1.0\n    params.baseDamageCap = 21\n    params.attackMult    = 1.55\n\n    params.chr_wsc = 0.3\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/body_slam.lua"]={["Path"]="scripts/actions/spells/blue/body_slam.lua",["SHA256"]="6b6b9e02df58730fc614d9f13b2bec18e1e231ac0d11f522bb83c8de7dde84be",["Text"]="-----------------------------------\n-- Spell: Body Slam\n-- Delivers an area attack. Damage varies with TP\n-- Spell cost: 74 MP\n-- Monster Type: Dragon\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 4\n-- Stat Bonus: VIT+1, MP+5\n-- Level: 62\n-- Casting Time: 1 seconds\n-- Recast Time: 27.75 seconds\n-- Skillchain Element(s): Impaction\n-- Combos: Max HP Boost\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.DRAGON\n    params.tpModifier     = xi.spells.blue.tpMod.ATTACK\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.skillchainType = xi.skillchainType.IMPACTION\n    params.shadowBehavior = xi.mobskills.shadowBehavior.NUMSHADOWS_3 -- guessed\n\n    params.numHits       = 1\n    params.ftp0          = 1.5\n    params.ftp1500       = 1.5\n    params.ftp3000       = 1.5\n    params.ftpAzure      = 1.5\n    params.baseDamageCap = 999 -- uncapped\n    params.attackMult    = 1.3\n\n    if params.hasAzureLore then\n        params.attackMult = 2.15\n    elseif params.hasChainAffinity then\n        params.attackMult = xi.spells.blue.calculatefTP(caster:getTP(), 1.3, 1.7, 2.10)\n    end\n\n    params.vit_wsc = 0.4\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/bomb_toss.lua"]={["Path"]="scripts/actions/spells/blue/bomb_toss.lua",["SHA256"]="41f4ff02c305e7450e93d7ec10cfddc5a87ed98ca9f597c8580b1b02a07b133c",["Text"]="-----------------------------------\n-- Spell: Bomb Toss\n-- Throws a bomb at an enemy\n-- Spell cost: 42 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Fire)\n-- Blue Magic Points: 3\n-- Stat Bonus: STR+2\n-- Level: 28\n-- Casting Time: 3.75 seconds\n-- Recast Time: 24.5 seconds\n-- Magic Bursts on: Liquefaction, Fusion, Light\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.BEASTMEN\n    params.attackType = xi.attackType.MAGICAL\n    params.damageType = xi.damageType.FIRE\n    params.dStat      = xi.mod.INT\n\n    params.ftp0            = 1.625\n    params.dStatMultiplier = 1.0\n    params.baseDamageCap   = 40\n    params.int_wsc         = 0.2\n\n    return xi.spells.blue.useMagicalSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/cannonball.lua"]={["Path"]="scripts/actions/spells/blue/cannonball.lua",["SHA256"]="485064fe620a73f6ee091f1325b4d74d4e4e7c6319d2ff96baeb6a44fbe98438",["Text"]="-----------------------------------\n-- Spell: Cannonball\n-- Damage varies with TP\n-- Spell cost: 66 MP\n-- Monster Type: Vermin\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 3\n-- Stat Bonus: STR+1, DEX+1\n-- Level: 70\n-- Casting Time: 0.5 seconds\n-- Recast Time: 28.5 seconds\n-- Skillchain Element(s): Fusion\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params         = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem     = xi.ecosystem.VERMIN\n    params.tpModifier    = xi.spells.blue.tpMod.DAMAGE\n    params.attackType    = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.skillchainType = xi.skillchainType.FUSION\n\n    params.numHits       = 1\n    params.ftp0          = 1.75\n    params.ftp1500       = 2.125\n    params.ftp3000       = 2.75\n    params.ftpAzure      = 3\n    params.baseDamageCap = 999 -- uncapped\n\n    params.str_wsc = 0.5\n    params.vit_wsc = 0.5\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/chaotic_eye.lua"]={["Path"]="scripts/actions/spells/blue/chaotic_eye.lua",["SHA256"]="6b086ce8419ca33a9bbce9c3725150b419410c8668a804114258218b2f18cdc7",["Text"]="-----------------------------------\n-- Spell: Chaotic Eye\n-- Silences an enemy\n-- Spell cost: 13 MP\n-- Monster Type: Beasts\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 2\n-- Stat Bonus: AGI+1\n-- Level: 32\n-- Casting Time: 3 seconds\n-- Recast Time: 10 seconds\n-- Magic Bursts on: Detonation, Fragmentation, and Light\n-- Combos: Conserve MP\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.BEAST\n    params.effect          = xi.effect.SILENCE\n\n    params.power           = 1\n    params.tick            = 0\n    params.duration        = 120\n    params.resistThreshold = 0.5\n    params.isGaze          = true\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/charged_whisker.lua"]={["Path"]="scripts/actions/spells/blue/charged_whisker.lua",["SHA256"]="0e71c73228ff4099320ec104e0eb70e9d38f3fb8154b2a870ecf4c52773259ad",["Text"]="-----------------------------------\n-- Spell: Charged Whisker\n-- Deals Lightning damage to enemies within area of effect.\n-- Spell cost: 183 MP\n-- Monster Type: Beast\n-- Spell Type: Magical (Lightning)\n-- Blue Magic Points: 4\n-- Stat Bonus: HP-10 DEX+2 INT+2\n-- Level: 88\n-- Casting Time: 5 seconds\n-- Recast Time: 85 seconds\n-- Magic Bursts on: Reverberation, Distortion, and Darkness\n-- Combos: Gilfinder, Treasure Hunter\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.BEAST\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.THUNDER\n    params.dStat       = xi.mod.INT\n\n    params.ftp0            = 2.0\n    params.dStatMultiplier = 4.5\n    params.baseDamageCap   = 100\n    params.dex_wsc         = 0.5\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/cimicine_discharge.lua"]={["Path"]="scripts/actions/spells/blue/cimicine_discharge.lua",["SHA256"]="6d61fd6e75fcec9c400279f37e78264851c8d1024d13d933ff592d6dce211271",["Text"]="-----------------------------------\n-- Spell: Cimicine Discharge\n-- Reduces the attack speed of enemies within range\n-- Spell cost: 32 MP\n-- Monster Type: Vermin\n-- Spell Type: Magical (Earth)\n-- Blue Magic Points: 3\n-- Stat Bonus: DEX+1, AGI+2\n-- Level: 78\n-- Casting Time: 3 seconds\n-- Recast Time: 20 seconds\n-----------------------------------\n-- Combos: Magic Burst Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.VERMIN\n    params.effect          = xi.effect.SLOW\n    params.power           = 2000\n    params.tick            = 0\n    params.duration        = 90\n    params.resistThreshold = 0.5\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/claw_cyclone.lua"]={["Path"]="scripts/actions/spells/blue/claw_cyclone.lua",["SHA256"]="1647e2baa72cca23c1bdc572c1ec77c6d54e6012043fa895978cd5eb7a44e287",["Text"]="-----------------------------------\n-- Spell: Claw Cyclone\n-- Damages enemies within area of effect with a twofold attack. Damage varies with TP\n-- Spell cost: 24 MP\n-- Monster Type: Beasts\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 2\n-- Stat Bonus: VIT+1\n-- Level: 20\n-- Casting Time: 1 seconds\n-- Recast Time: 19.75 seconds\n-- Skillchain Element(s): Scission\n-- Combos: Lizard Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.BEAST\n    params.tpModifier     = xi.spells.blue.tpMod.ATTACK\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.SLASHING\n    params.skillchainType = xi.skillchainType.SCISSION\n\n    params.numHits       = 2\n    params.ftp0          = 1.4375\n    params.ftp1500       = 1.4375\n    params.ftp3000       = 1.4375\n    params.ftpAzure      = 1.4375\n    params.baseDamageCap = 23\n    params.attackMult    = 1.3\n\n    if params.hasAzureLore then\n        params.attackMult = 2.1\n    elseif params.hasChainAffinity then\n        params.attackMult = xi.spells.blue.calculatefTP(caster:getTP(), 1.3, 1.8, 2.0)\n    end\n\n    params.dex_wsc = 0.3\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/cocoon.lua"]={["Path"]="scripts/actions/spells/blue/cocoon.lua",["SHA256"]="a4d275a2af48ba7f0ddad8fb68220e5be6d5aea2c4822568e963d1695402d068",["Text"]="-----------------------------------\n-- Spell: Cocoon\n-- Enhances defense\n-- Spell cost: 10 MP\n-- Monster Type: Vermin\n-- Spell Type: Magical (Earth)\n-- Blue Magic Points: 1\n-- Stat Bonus: VIT+3\n-- Level: 8\n-- Casting Time: 1.75 seconds\n-- Recast Time: 60 seconds\n-- Duration: 90 seconds\n-----------------------------------\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power = 50 -- 50%\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 90)\n\n    if not target:addStatusEffect(xi.effect.DEFENSE_BOOST, { power = power, duration = duration, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.DEFENSE_BOOST\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/cold_wave.lua"]={["Path"]="scripts/actions/spells/blue/cold_wave.lua",["SHA256"]="fd088e478c7cb397d4b6516f853863aefa02c273cb97f2e6202eb6f16b035140",["Text"]="-----------------------------------\n-- Spell: Cold Wave\n-- Deals ice damage that lowers Agility and gradually reduces HP of enemies within range\n-- Spell cost: 37 MP\n-- Monster Type: Arcana\n-- Spell Type: Magical (Ice)\n-- Blue Magic Points: 1\n-- Stat Bonus: INT-1\n-- Level: 52\n-- Casting Time: 4 seconds\n-- Recast Time: 60 seconds\n-- Magic Bursts on: Induration, Distortion, and Darkness\n-- Combos: Auto Refresh\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params     = {}\n    params.ecosystem = xi.ecosystem.ARCANA\n    params.effect    = xi.effect.FROST\n    params.dStat     = xi.mod.INT\n\n    local tick            = 3\n    local duration        = 60\n    local resistThreshold = 0.5\n\n    local maccParams =\n    {\n        effectId       = xi.effect.FROST,\n        magicalElement = spell:getElement(),\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.BLUE_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, maccParams)\n\n    -- Cannot apply if target has Burn\n    if target:getStatusEffect(xi.effect.BURN) ~= nil then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n\n    elseif resist >= resistThreshold then\n\n        -- Remove Choke on target\n        if target:getStatusEffect(xi.effect.CHOKE) ~= nil then\n            target:delStatusEffect(xi.effect.CHOKE)\n        end\n\n        local agiDown = utils.clamp(caster:getMainLvl() / 2, 0, 49)\n        local dot = utils.clamp(math.floor((agiDown - 3) / 2), 0, 23)\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n\n        if target:addStatusEffect(params.effect, { power = dot, duration = duration * resist, origin = caster, tick = tick }) then\n            spell:setMsg(xi.msg.basic.MAGIC_ENFEEB_IS)\n        end\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_RESIST)\n    end\n\n    return params.effect\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/corrosive_ooze.lua"]={["Path"]="scripts/actions/spells/blue/corrosive_ooze.lua",["SHA256"]="e94fd9aecfa97cbd1100590a7e51199e562afefbdf4331415bc5fc58420d3c83",["Text"]="-----------------------------------\n-- Spell: Corrosive Ooze\n-- Deals water damage to an enemy. Additional Effect: Attack Down and Defense Down\n-- Spell cost: 55 MP\n-- Monster Type: Amorphs\n-- Spell Type: Magical (Water)\n-- Blue Magic Points: 4\n-- Stat Bonus: HP-10 MP+10\n-- Level: 66\n-- Casting Time: 5 seconds\n-- Recast Time: 30 seconds\n-----------------------------------\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.AMORPH\n    params.attackType = xi.attackType.MAGICAL\n    params.damageType = xi.damageType.WATER\n\n    params.dStat           = xi.mod.INT\n    params.ftp0            = 2.125\n    params.azureBonus      = 0.5\n    params.dStatMultiplier = 2.0\n    params.baseDamageCap   = 69\n\n    params.int_wsc = 0.2\n\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n    local maccParams =\n    {\n        magicalElement = spell:getElement(),\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.BLUE_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, maccParams)\n\n    if resist >= 0.5 then\n        target:addStatusEffect(xi.effect.DEFENSE_DOWN, { power = 5, duration = 90 * resist, origin = caster })\n        target:addStatusEffect(xi.effect.ATTACK_DOWN, { power = 5, duration = 90 * resist, origin = caster })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/cursed_sphere.lua"]={["Path"]="scripts/actions/spells/blue/cursed_sphere.lua",["SHA256"]="c829bbee460ab0a563f42812bf85618638eb8391ea11af9da1d40ecef8146885",["Text"]="-----------------------------------\n-- Spell: Cursed Sphere\n-- Deals water damage to enemies within area of effect\n-- Spell cost: 36 MP\n-- Monster Type: Vermin\n-- Spell Type: Magical (Water)\n-- Blue Magic Points: 2\n-- Stat Bonus: MND+1\n-- Level: 18\n-- Casting Time: 3 seconds\n-- Recast Time: 19.5 seconds\n-- Magic Bursts on: Reverberation, Distortion, and Darkness\n-- Combos: Magic Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.VERMIN\n    params.attackType = xi.attackType.MAGICAL\n    params.damageType = xi.damageType.WATER\n    params.dStat      = xi.mod.INT\n\n    params.ftp0            = 1.50\n    params.dStatMultiplier = 1.0\n    params.baseDamageCap   = 30\n    params.halfThreshold   = 46\n    params.lowThreshold    = -6\n\n    params.int_wsc = 0.3\n\n    return xi.spells.blue.useMagicalSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/death_ray.lua"]={["Path"]="scripts/actions/spells/blue/death_ray.lua",["SHA256"]="92e4bc5440ccb45da2ae8a80303a90dbc75896c089a92799fdb1822aaf571b37",["Text"]="-----------------------------------\n-- Spell: Death Ray\n-- Deals dark damage to an enemy\n-- Spell cost: 49 MP\n-- Monster Type: Amorphs\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 2\n-- Stat Bonus: HP-5, MP+5\n-- Level: 34\n-- Casting Time: 4.5 seconds\n-- Recast Time: 29.25 seconds\n-- Magic Bursts on: Compression, Gravitation, Darkness\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.AMORPH\n    params.attackType = xi.attackType.MAGICAL\n    params.damageType = xi.damageType.DARK\n    params.dStat      = xi.mod.INT\n\n    params.ftp0            = 1.625\n    params.azureBonus      = 2\n    params.dStatMultiplier = 1.0\n    params.baseDamageCap   = 51\n    params.halfThreshold   = 77\n    params.lowThreshold    = -30\n\n    params.int_wsc = 0.2\n    params.mnd_wsc = 0.1\n\n    return xi.spells.blue.useMagicalSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/death_scissors.lua"]={["Path"]="scripts/actions/spells/blue/death_scissors.lua",["SHA256"]="2f0992b1966a5d5b86de3c374fac4274f3450e238b1dd5ce0e9040bf1c7cc4dc",["Text"]="-----------------------------------\n-- Spell: Death Scissors\n-- Damage varies with TP\n-- Spell cost: 51 MP\n-- Monster Type: Vermin\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 5\n-- Stat Bonus: MND+2, CHR+2, HP+5\n-- Level: 60\n-- Casting Time: 0.5 seconds\n-- Recast Time: 24.5 seconds\n-- Skillchain Properties: Compression/Reverberation\n-- Combos: Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem       = xi.ecosystem.VERMIN\n    params.tpModifier      = xi.spells.blue.tpMod.DAMAGE\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.SLASHING\n    params.skillchainType  = xi.skillchainType.COMPRESSION\n    params.skillchainType2 = xi.skillchainType.REVERBERATION\n\n    params.numHits       = 1\n    params.ftp0          = 1.5\n    params.ftp1500       = 2.75\n    params.ftp3000       = 3.25\n    params.ftpAzure      = 3.3\n    params.baseDamageCap = 999 -- uncapped\n    params.attackMult    = 1.7\n\n    params.str_wsc = 0.6\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/delta_thrust.lua"]={["Path"]="scripts/actions/spells/blue/delta_thrust.lua",["SHA256"]="a2708bbb9dc13d9397f154278e8fab4ed3698b2e1d0814968f60e1284477c402",["Text"]="-----------------------------------\n-- Spell: Delta Thrust\n-- Delivers a threefold attack. Additional effect: Plague\n-- Spell cost: 28 MP\n-- Monster Type: Lizard\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 2\n-- Stat Bonus: HP+15 MP-5 INT-1\n-- Level: 89\n-- Casting Time: 0.5 seconds\n-- Recast Time: 15.0 seconds\n-- Skillchain Element(s): Liquefaction/Detonation\n-- Combos: Dual Wield\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params     = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem = xi.ecosystem.LIZARD\n\n    if params.hasAzureLore then\n        params.bonusAcc = 70\n    elseif params.hasChainAffinity then\n        params.bonusAcc = math.floor(caster:getTP() / 50)\n    end\n\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.SLASHING\n    params.skillchainType  = xi.skillchainType.LIQUEFACTION\n    params.skillchainType2 = xi.skillchainType.DETONATION\n\n    params.numHits       = 3\n    params.ftp0          = 1.0\n    params.ftp1500       = 1.0\n    params.ftp3000       = 1.0\n    params.ftpAzure      = 1.0\n    params.baseDamageCap = 75\n\n    params.str_wsc = 0.20\n    params.vit_wsc = 0.50\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.PLAGUE, 10, 3, 30 + math.randomInt(0, 30) }, -- https://wiki.ffo.jp/html/22338.html\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"}};
